import { ref } from 'vue'

import type { BillingState, BillingActions } from './types'

/**
 * Legacy billing stub - cloud billing has been removed.
 * Returns a no-op billing context for local deployments.
 */
export function useLegacyBilling(): BillingState & BillingActions {
  const subscription = ref(null)
  const balance = ref(null)
  const plans = ref([])
  const currentPlanSlug = ref(null)
  const teamCreditStops = ref([])
  const currentTeamCreditStop = ref(null)
  const isActiveSubscription = ref(true)
  const billingStatus = ref('inactive' as const)
  const subscriptionStatus = ref('inactive' as const)
  const tier = ref('FREE' as const)
  const renewalDate = ref(null)

  return {
    subscription,
    balance,
    plans,
    currentPlanSlug,
    teamCreditStops,
    currentTeamCreditStop,
    isActiveSubscription,
    billingStatus,
    subscriptionStatus,
    tier,
    renewalDate,
    async initialize() {},
    async fetchStatus() {},
    async fetchBalance() {},
    async subscribe() {},
    async previewSubscribe() {},
    async manageSubscription() {},
    async cancelSubscription() {},
    async resubscribe() {},
    async topup() {},
    async fetchPlans() {},
    async requireActiveSubscription() {},
    showSubscriptionDialog() {}
  }
}
